from lib import *
S = SS('s49')
steps = [
    step("start() 一口气 yield N 个请求而下载很慢(并发 1、每个 0.5 s),请求全部积压在调度器里。内存队列:N = 10,000 时 start() 耗时 0.17 s、积压 9,999 个(第一个已出队)、进程 RSS 增量 10.3 MiB(每个请求约 1.05 KiB);N = 50,000 时 0.91 s、54.9 MiB(约 1.12 KiB)。同样的负载启用 JOBDIR(磁盘队列):耗时 0.22 s 和 1.07 s,RSS 增量只有 0.3 MiB 和 0.2 MiB。内存队列的开销随请求数线性增长,磁盘队列几乎不占内存,速度只慢约 20%。", t=tl(S(1)), mark=lidx(S(1), '50000磁盘', '10000磁盘'), done=lidx(S(1), '50000内存', '10000内存'), b=bars([['50,000 个 内存队列', 54.9, '54.9 MiB'], ['50,000 个 JOBDIR', 0.2, '0.2 MiB']], 54.9, mark=[1], done=[0]), kv=KV([['内存队列', '约 1 KiB/请求,线性增长'], ['JOBDIR 磁盘队列', 'RSS 几乎不变(0.2 MiB)'], ['start() 耗时', '0.91 s → 1.07 s(50,000 个)']], ['JOBDIR 磁盘队列'])),
    step("请求带的 meta 也算在内存里:50,000 个请求每个带 1 KB 的 meta(每个字符串不同),内存队列的 RSS 增量涨到 120.1 MiB(约 2.46 KiB/请求),比不带 meta 的 54.9 MiB 多出约 65 MiB;start() 耗时 0.94 s。别在 meta 里塞大对象。", t=tl(S(2)), mark=lidx(S(2), '带 1 KB meta'), kv=KV([['无 meta', '54.9 MiB / 50,000 个'], ['每个请求 1 KB meta', '120.1 MiB'], ['结论', 'meta 里的内容全在内存队列里']], ['结论'])),
    step("落盘后的 JOBDIR:50,000 个请求,磁盘队列文件总共 11.1 MiB,每个请求约 234 字节(序列化后的请求比内存里对象的 1 KiB 小得多)。用磁盘换内存的代价是序列化耗时和磁盘空间,以及请求必须可序列化(见 JOBDIR 那一篇)。", t=tl(S(3)), mark=lidx(S(3), 'JOBDIR 总大小'), kv=KV([['50,000 个请求', '11.1 MiB'], ['每个请求', '约 234 字节'], ['代价', '序列化 + 请求必须能 pickle']], ['50,000 个请求'])),
]
A = mkarts('s49', 49, 'Scrapy,请求积压,内存队列,JOBDIR,RSS,真实验证,动画演示',
    '实测请求积压的内存:内存队列每个请求约 1 KiB(50,000 个增加 54.9 MiB,带 1 KB meta 变 120.1 MiB),启用 JOBDIR 后 RSS 只涨 0.2 MiB、start() 慢约 20%、落盘 11.1 MiB(每个请求约 234 字节)。',
    '爬虫发现的链接比下载的速度快得多时,请求会堆在调度器里。内存队列每个请求占多少?meta 里的东西算不算?JOBDIR 能省多少内存、代价是什么?这篇用 5 万个积压请求量一遍。',
    [('≈ 1 KiB', '内存队列里一个积压请求的内存(50,000 个增加 54.9 MiB)'), ('0.2 MiB', '同样 50,000 个请求用 JOBDIR 时进程 RSS 的增量'), ('234 字节', 'JOBDIR 里一个请求落盘后的大小')],
    [('内存队列', '<p>默认队列把每个等待下载的请求都留在内存里,大小随请求数线性增长,meta 里放的东西也算在内。</p>'),
     ('磁盘队列', '<p>设了 <code>JOBDIR</code> 之后请求序列化到磁盘队列,进程内存几乎不再随积压增长,代价是序列化耗时(这里约 20%)和请求必须可 pickle。</p>'),
     ('什么时候要在意', '<p>上百万级积压(比如 start() 一次产出全部 URL)时内存队列会占 GB 级内存;此时改用 JOBDIR,或让 start() 按下载节奏分批产出。</p>')],
    steps,
    [ENV_Y + '。并发 1、服务器每个请求 0.5 s,爬虫 6 秒后被 CLOSESPIDER_TIMEOUT 关闭;RSS 增量取 start() 开始到结束 ru_maxrss 的变化(峰值,单位 macOS 字节);请求用 dont_filter 避免去重集合的内存干扰',
     '没有验证:百万级积压的真实内存;去重指纹集合的内存(见去重那一篇:每个指纹约 87 字节,另外计);DownloaderAwarePriorityQueue 多槽(多域名)时每槽的队列开销;磁盘队列读回(出队)的耗时;JOBDIR 下 SCHEDULER_MEMORY_QUEUE 与磁盘队列同时使用的比例'],
    '请求积压')
